function deform(){if(!base)return;const a=geom.attributes.position.array;const coord=i=>[base[i*3],base[i*3+1]];const [nx,ny]=coord(1),[bx,by]=coord(6),[cx,cy]=coord(152),[ux,uy]=coord(0),[lx,ly]=coord(17);for(let i=0;i<base.length/3;i++){let x=base[i*3],y=base[i*3+1],z=base[i*3+2];if(!showOriginal){const nose=g(x,y,nx,ny,.12,.12),bridge=g(x,y,bx,by,.09,.22),chin=g(x,y,cx,cy,.25,.17),up=g(x,y,ux,uy,.22,.055),lo=g(x,y,lx,ly,.22,.065);z+=values.bridge/100*.10*bridge+values.tip/100*.12*nose+values.chin/100*.14*chin+values.upper/100*.07*up+values.lower/100*.07*lo;x+=(x-nx)*values.width/100*.28*nose;y-=values.length/100*.12*chin;y+=values.upper/100*.025*up-values.lower/100*.025*lo}a[i*3]=x;a[i*3+1]=y;a[i*3+2]=z}geom.attributes.position.needsUpdate=true;geom.computeVertexNormals();render()}
